INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(343000, 0, 3430, 0, 0, 0, 'Eversong Woods', 'Eversong Woods is the northern heart of Quel''Thalas, a forest of golden leaves that the magisters of old bound in a perpetual spring. Silvermoon City rises in its northeast, and Sunstrider Isle lies just off its northern shore. The land still bears the wound of the Third War. When Arthas led the Scourge to the Sunwell, his army tore a blighted road through the forest and into the capital itself, and that black furrow, the Dead Scar, still draws the undead north from the Ghostlands. With the Sunwell lost, the survivors took the name blood elves and learned to sate their hunger for magic from other sources. Those who cannot master that hunger become the Wretched, who raid roads and ruins for any scrap of power. Arcane sanctums now draw energy from the ley lines, the Farstriders hold the Amani trolls at bay in the southeast, and many elves still speak of finding their true fate in Outland.', 'warcraft.wiki.gg/wiki/Eversong_Woods (perpetual springtime, Dead Scar, Wretched, sanctums, Amani); page_text 2823-2827 (Saga of the Sin''dorei: Sunwell, Arthas, renamed blood elves); npc_text 8534 (sanctums siphon ley-line power); quest 8476 description (Amani raids); quest 9255 reward text (true fate in Outland); warcraft.wiki.gg/wiki/Dead_Scar'),
(343001, 1, 3430, 1, 0, 0, 'Sunstrider Isle', 'Sunstrider Isle, off the northern shore of Eversong, was once a tranquil place of study, its creatures bound to calm by the spells of the magisters. When the Scourge destroyed the Sunwell, that control shattered. Mana wyrms set to guard the floating Burning Crystals now roam errant, lynxes have been warped by the crystals'' unchecked power, and the tenders that once kept the gardens attack on sight. From the Sunspire, the great tower of the isle, Magistrix Erona and her fellow teachers instruct a new generation, while Well Watcher Solanian keeps his long vigil over the Sunwell from the tower''s upper platform. A bridge to the south carries the outrunners'' road to the mainland.', 'quest 8325, 8326, 8334 descriptions; quest 8336 description and request text (tranquil place of study; creatures bound into complacency until the Sunwell fell); quest 8330 request text (vigil over the Sunwell, or what remains of it); quest 8347 description (bridge leading south); npc_text 16703 (Erona); warcraft.wiki.gg/wiki/Sunstrider_Isle; subzone list: 3484 The Sunspire'),
(343002, 1, 3430, 2, 0, 0, 'Falthrien Academy', 'West of the Sunspire floats Falthrien Academy, a great building crowned with ornate spires that once served the scholars of the isle. It has fallen to Felendren the Banished, a former student who ignored the warnings of his teachers and gave himself over to his craving for magic until he became one of the Wretched. Exiled from elven lands, he has made his lair atop the academy, served by arcane wraiths. Some of those wraiths carry dark, tainted slivers of crystallized mana, and the arcanists of the Sunspire suspect such slivers may help reveal the strange corruption that grips the isle.', 'quest 8327 reward text (huge floating building with ornate spires, to the west); quest 8335 description; quest 8338 description and reward text; warcraft.wiki.gg/wiki/Felendren_the_Banished; DB spawn: Felendren 15367'),
(343003, 1, 3430, 3, 0, 0, 'Shrine of Dath''Remar', 'On the western side of Sunstrider Isle stands a shrine to Dath''Remar Sunstrider, first king of the high elves. Ages ago he led the exiled Highborne away from Kalimdor and through the storms of the Maelstrom in search of a new homeland, and the name Sunstrider, he who walks the day, began with him. A bronze placard on the shrine calls him a noble elf and declares that all who prosper in Quel''Thalas do so thanks to him. Well Watcher Solanian urges every newcomer to read it. Lately visitors feel an uneasy pulse of the same strange power that has gripped the rest of the isle.', 'quest 8345 description and reward text; page_text 2936 (placard text and the strange power); page_text 1847, 1854 (Highborne exile, Maelstrom, Sunstrider means he who walks the day); gameobject 180516 Shrine of Dath''Remar'),
(343004, 1, 3430, 4, 0, 0, 'Ruins of Silvermoon', 'The western half of Silvermoon City never recovered from the day the Scourge broke through it on the march to the Sunwell. Its lanes and halls stand empty and cracked, and they have become a haunt of the Wretched, who will kill for a handful of mana crystals. Even Dawning Lane, the safest road through, is no guarantee: the outrunners who run goods south from Sunstrider Isle fear the Wretched have caught their last courier somewhere along it. Arcane patrollers built by earlier generations to guard the city still walk their rounds, calling on all to uphold the law, but they no longer recognize the elves as their masters. The Wretched ringleader Thaelis the Hungerer hides in the Commons Hall.', 'warcraft.wiki.gg/wiki/Ruins_of_Silvermoon (western half, Dead Scar, Wretched); quest 9704 description and 9705 reward text (third outrunner this month); quest 8472 description (patrollers crafted by our forefathers, attack on sight); creature_text 15638 (Uphold the law); warcraft.wiki.gg/wiki/Thaelis_the_Hungerer (Commons Hall); subzone list: 3532 Dawning Lane, 3531 Skulking Row, 3534 Feth''s Way, 3662 Commons Hall; quest 8350 description (safety of Dawning Lane); DB spawns: Slain Outrunner 17849 in 3532; Thaelis 15949 terrain area 3533'),
(343005, 1, 3430, 5, 0, 0, 'Falconwing Square', 'Falconwing Square sits in the southeastern corner of the Ruins of Silvermoon, at the end of Dawning Lane, the one corner of the ruined district where order has been restored. Its inn is the first stop on the mainland for the graduates of Sunstrider Isle, and trainers of many crafts and callings teach nearby. Aeldon Sunbrand, captain of the Blood Hawks, directs the struggle against the Wretched from here, and Magister Jaronis gathers the arcane cores of broken patrollers to make up for sanctums running below full strength. In the square Sergeant Kan''ren questions a captured Wretched, whose kind have killed two of his men this month, and a posted bounty names Thaelis the Hungerer.', 'warcraft.wiki.gg/wiki/Falconwing_Square; quest 8350 (Erona''s package to the inn); quest 8472 description and reward text; npc_text 8229 (Sunbrand); npc_text 8698 and creature_text 16924 (Kan''ren); gameobject 180918 Wanted: Thaelis the Hungerer; creature_template 15403 subname Captain of the Blood Hawks; quest 8472 reward text (sanctums not at full capacity); warcraft.wiki.gg/wiki/Falconwing_Square (southeastern corner, end of Dawning Lane)'),
(343006, 1, 3430, 6, 0, 0, 'North Sanctum', 'Southwest of Falconwing Square stands the North Sanctum, one of the arcane sanctums that now sustain Quel''Thalas. Currents of ley energy, invisible to the naked eye, run beneath the land, and the sanctums siphon power from them, a steady source of energy that took the place of the Sunwell when it fell. Ley-Keeper Caidanis oversees its upkeep. Of late he has also played host to Prospector Anvilward, a dwarven envoy from Ironforge, and has remarked that the guest''s enthusiastic interest in the sanctums'' operations is most unexpected.', 'quest 8895 description (southwest of Falconwing Square); npc_text 8534 (ley-line currents invisible to the naked eye; steady source of energy); creature_text 15405, 15420; quest 8482 reward text (envoy from Ironforge); warcraft.wiki.gg/wiki/North_Sanctum'),
(343007, 1, 3430, 7, 0, 0, 'West Sanctum', 'The West Sanctum, southwest of the North Sanctum, is one of the primary sources of arcane power in the region, and it is badly broken. Ley-Keeper Velania warned against raising the load it carried, and when one of its energy converters was destroyed, manawraiths and mana stalkers came pouring out of the structure. The accident has set rumors of Darnassian sabotage running through Eversong, though most reports of night elves in the woods prove unfounded.', 'quest 9119 description (southwest of the North Sanctum); quest 8486 description; quest 9352 description and reward text (primary energy source, Darnassian rumors); quest 8482 description and reward text; DB spawns: Darnassian Scout 15968 x5 near Ley-Keeper Velania 15401; quest 9352 description (most reports unfounded)'),
(343008, 1, 3430, 8, 0, 0, 'Tranquil Shore and Golden Strand', 'Along the western coast of Eversong, the Tranquil Shore and the Golden Strand have been overrun by Grimscale murlocs. From a bluff above the shore, the Farstrider Hathvelion Sungaze has vowed to drive them back to the murky depths, though so far the murlocs show no sign of retreat. Their self-styled chieftain, Mmmrrrggglll, wanders the strand south of the river inlet, flaunting the ring of a friend of Hathvelion''s whom he slew. The Grimscale are bold raiders too: from their huts near Sunsail Anchorage they have carried off a merchant captain''s cargo.', 'quest 8884 description, request and reward text; quest 8885 description and reward text; quest 8886 description (huts west and south of the anchorage on the Golden Strand); quest 8887; DB spawns: Hathvelion 15920, Mmmrrrggglll 15937'),
(343009, 1, 3430, 9, 0, 0, 'Sunsail Anchorage', 'Sunsail Anchorage, west of Fairbreeze Village, is the shipyard of Eversong, and some of its vessels date back to the Second War. The elves had reclaimed it once, but a bold attack by the Wretched drove them out again and left the yard in the hands of thugs and hooligans led by Aldaron the Reckless, who holds the top floor of the building beside the anchorage. The defenders retreated so hastily that most of their weapons were left behind. Velendris Whitemorn and his rangers now hold a guarded camp just to the east, where the merchant Captain Kelisendra waits for the chance to repair her ship and sail again.', 'warcraft.wiki.gg/wiki/Sunsail_Anchorage (ships from the Second War, reclaimed then lost to Aldaron); quest 8892 description (west of Fairbreeze); quests 8480, 9076 descriptions; quest 8886 and 8887 reward and request texts; DB spawns: Aldaron the Reckless 16294, Velendris 15404, Kelisendra 15921; CreatureDisplayInfo/Extra.dbc: display 15915 male blood elf'),
(343010, 1, 3430, 10, 0, 0, 'Saltheril''s Haven', 'Down the road west of Fairbreeze Village lies Saltheril''s Haven, the country estate of Lord Saltheril, where the party never seems to end. While rangers bleed on the borders, the lord and his guests toast the magnificence of Quel''Thalas with wine from Silvermoon, springpaw appetizers and fireworks, and his companion Elisara Sunstriker muses about an evening picnic within sight of the fighting. The estate is not wholly idle: teachers of alchemy, enchanting, tailoring and herbalism keep their trades on its grounds. Magistrix Landra Dawnstrider of Fairbreeze considers its master a fool living in denial of the war.', 'quest 9395 description; quest 9067 description; creature_text 16147 (Elisara); DB spawns at area 3468: Arcanist Sheynathren, Magistrix Eredania, Sempstress Ambershine; Botanist Tyniarrel nearby; warcraft.wiki.gg/wiki/Saltheril''s_Haven'),
(343011, 1, 3430, 11, 0, 0, 'Fairbreeze Village', 'Fairbreeze Village is the chief settlement of southern Eversong, led by Magistrix Landra Dawnstrider and still standing, as its people say, as a testament to elven tenacity. It is pressed from two sides, by the Scourge coming up the Dead Scar to the east and by the Wretched of Sunsail Anchorage to the west, and reinforcements from Silvermoon are slow to come. Ranger Sareyn holds the eastern road against the undead, Ranger Degolien has been sent to deal with the Wretched, and the craftsman Velan Brightoak trades armor for springpaw pelts, grumbling that night elf poachers travel all this way to take them.', 'warcraft.wiki.gg/wiki/Fairbreeze_Village (village leader Landra Dawnstrider); npc_text 8535 (Ardeyn: testament to our race''s tenacity); quest 9358 description (Scourge on the east, Wretched to the west); quest 9252 description (no sign of reinforcements); quest 9256 reward text; quest 8491 description (night elf poachers)'),
(343012, 1, 3430, 12, 0, 0, 'The Dead Scar', 'The Dead Scar is the path Arthas carved through Quel''Thalas on his march to the Sunwell, where he meant to raise Kel''Thuzad. Wherever the Scourge passed, the land was blighted, and a long black furrow of dead soil now runs from the Ghostlands across the Elrendar River, through the heart of Eversong and in at the broken gates of Silvermoon City. The taint still draws the undead. Plaguebone pillagers, rotlimb marauders and darkwraiths trudge up the Scar from the south, and rangers such as Jaela spend long days cutting them down within sight of the capital.', 'warcraft.wiki.gg/wiki/Dead_Scar (pre-Cataclysm sections); quest 8475 description; quest 9252 objectives; npc_text 8403 and creature_text 15416 (Ranger Jaela); page_text 2824 (Kel''Thuzad raised with the Sunwell); warcraft.wiki.gg/wiki/Dead_Scar (across the Elrendar River, shattered main gates)'),
(343013, 1, 3430, 13, 0, 0, 'East Sanctum', 'The East Sanctum stood squarely in the way when Arthas drove his army toward Silvermoon, and it has been useless ever since. Its ley energies are disrupted, its soil tainted and its grounds a magnet for the undead. Apprentice Mirveda, pursuing research that her former mentor, Magistrix Landra Dawnstrider of Fairbreeze, long ago lost faith in, has come here to learn whether the damage can be undone. She means to gather samples of the tainted soil and study them, hoping that in time the land might be set right.', 'quest 8487 description; quest 8488 reward text; quest 9254 description and reward text; quest 9255 description and reward text; creature_text 15402; creature_questender/starter: 9254 from and 9255 to Landra Dawnstrider 16210'),
(343014, 1, 3430, 14, 0, 0, 'Stillwhisper Pond', 'Southeast of Silvermoon City lies Stillwhisper Pond, where Instructor Antheol delivers his lectures on the elements. He likens students to sheep, likeable enough while watched but apt to fall off a cliff or drown in a shallow river the moment they are left alone. Two of his apprentices, Meledor and Ralen, are out on the road south of the city with a load of magical goods, their master''s precious elemental grimoire among them, and the Wretched who prowl that road will take anything that holds a trace of magic.', 'quest 9064 description (southeast of Silvermoon); npc_text 9061 (students are like sheep); quests 9035, 9062, 9066 descriptions and reward texts; creature_text 15941, 15945; warcraft.wiki.gg/wiki/Stillwhisper_Pond'),
(343015, 1, 3430, 15, 0, 0, 'Farstrider Retreat', 'Farstrider Retreat, south of Silvermoon City in eastern Eversong, is a lodge of the Farstriders, rangers sworn to defend their people from enemies near and far. Under Lieutenant Dawnrunner they hold the line against the Amani trolls of Zeb''Watha and Tor''Watha, whose raids come almost daily. Arathel Sunforge works the forge here and, for all the old enmity between the races, admits a craftsman''s admiration for Amani weapons. The lodge has also taken in Magister Duskwither, who has shut down his school at a spire to the north for reasons he will not share. Just to the south, Elrendar Falls spill down from Lake Elrendar.', 'npc_text 8755 (Dawnrunner: rangers sworn to defend our people from enemies both near and far); quest 8476 description; quest 8477 description; quest 9617 description (Farstrider Retreat lies south of Silvermoon); quest 8888 description and 8890 reward text; page_text 2853 (sabbatical at the Farstrider Retreat); warcraft.wiki.gg/wiki/Elrendar_Falls (just south of Farstrider Retreat)'),
(343016, 1, 3430, 16, 0, 0, 'Duskwither Spire', 'North of Farstrider Retreat, where the road branches east, Duskwither Spire floats above its grounds, reached by an orb of translocation in the pavilion below. Magister Duskwither kept a school here until he suddenly emptied it, and the Spire''s power sources still run. Strange magical creatures, mana serpents and ether fiends among them, now overrun the place, and a rarely seen arcane elemental named Eldinarcus roams the grounds. Groundskeeper Wyllithen, whom nobody remembered to tell to leave, still tries to keep the gardens in order.', 'quest 8888 description (route from the retreat); quest 8891 reward text; page_text 2846-2853 (Duskwither''s journal); quests 8894, 9394; warcraft.wiki.gg/wiki/Duskwither_Spire (orb of translocation in a pavilion beneath); warcraft.wiki.gg/wiki/Eldinarcus (rare, Duskwither Grounds); DB: Eldinarcus 16854 rank 4, 3 spawn points in area 3480; quest 8889 description (three power sources still running)'),
(343017, 1, 3430, 17, 0, 0, 'The Scorched Grove', 'In the southwest of Eversong, the westernmost of the runestones that warded the border was destroyed in a Scourge attack. To keep the plague''s taint from spreading, the elves burned the forest around it, a decision their rangers still call one of the hardest of these times. The treants who had long been friends to Quel''Thalas would not accept the loss, and their withered green keepers labor to make the grove grow again, so the elves must now cut down their old allies. Larianna Riverwind watches over the grove from a tower to the northwest, and Old Whitebark, elder of the treants, wanders the ashes.', 'quest 9258 description; quest 8473 description and reward text; npc_text 8504 (Western Runestone failed long ago); quest 10166 description (treant elder); warcraft.wiki.gg/wiki/Scorched_Grove (treants try to nurture life back); DB spawns: Withered Green Keeper 15637 x44, Old Whitebark 15409'),
(343018, 1, 3430, 18, 0, 0, 'Runestones Falithas and Shan''dor', 'Along the southern edge of Eversong stand Runestone Falithas and Runestone Shan''dor, two of the few surviving stones that once raised a protective barrier across the border with the Ghostlands. Many were destroyed in Arthas''s attack and others were stolen. Runewarden Deryan has sworn that while he lives the remaining stones will not fail. Falithas, where he keeps watch, is the only one still at full strength. The stone to its east has gone dark, but it may yet be recharged with an infused crystal, if its defenders can hold off the Scourge drawn to it while the energy takes hold.', 'quest 8490 description and reward text; npc_text 8504 (Deryan''s oath); quest 9253 description; warcraft.wiki.gg/wiki/Runestone_Falithas (only one fully intact and functional); warcraft.wiki.gg/wiki/Runestone_Shan''dor (deactivated, reclaimed with energy from an arcane crystal); DB: Infused Crystal Focus 181164 spawned in area 3914 (Runestone Shan''dor), east of Deryan 16362 in 3913'),
(343019, 1, 3430, 19, 0, 0, 'Zeb''Watha and Tor''Watha', 'In the southeast of Eversong, beyond the Farstrider Retreat, the Amani trolls keep two villages on either side of Lake Elrendar. Tor''Watha is the larger, home to berserkers, axe throwers and the spearcrafter Otembe, whose magical hammer is said to be so light and well balanced that it lets him work with rare skill. Caged there, poisoned and left to die, is Ven''jashi, a Darkspear troll and sworn enemy of the Amani. Across the water at Zeb''Watha rules Chieftain Zul''Marosh, whose warriors raid elven lands almost daily.', 'quest 8476 description; quest 8477 description; quest 8479 description, log text and reward text; quest 9360 description; warcraft.wiki.gg/wiki/Zeb''Watha (much smaller than Tor''Watha, chieftain); DB spawns: Otembe 15408, Ven''jashi 15406, Tregla 16855 (area 3476), Zul''Marosh 15407'),
(343020, 2, 3430, 1, 2, 0, 'Well Watcher Solanian', 'Well Watcher Solanian keeps his vigil over the Sunwell from an upper platform of the Sunspire, where he has watched his people''s lives turned upside down. Some accuse him of dwelling too much on the past, and he does insist that every visitor to Sunstrider Isle honor the shrine of Dath''Remar. Yet his counsel looks forward. The blood elves, he teaches, are survivors, and each of them must master the endless hunger for magic before it masters them. Young students of the Sunspire are sent up to him once their first lessons are done, and he puts them to work reclaiming the isle.', 'npc_text 7784; quest 8345 description; quest 8330 description and request text; quests 10068-10073 (trainers send students to him); creature_template 15295 faction 1604; quest 8330 description (vigil over the Sunwell)'),
(343021, 2, 3430, 2, 0, 0, 'Felendren the Banished', 'Felendren was once a pupil on Sunstrider Isle. He refused to heed the warnings of his mentors and elders, never learned to control his craving for magic, and succumbed to it, becoming one of the Wretched, a shell of the elf he had been. Banished from blood elf lands, he now lurks atop Falthrien Academy with arcane wraiths as his servants, a threat to the Sunspire itself. The teachers of the isle hold him up as a warning that every blood elf shares the same potential fate.', 'quest 8335 description, request and reward texts; page_text 2848 (Duskwither''s journal on Felendren); warcraft.wiki.gg/wiki/Felendren_the_Banished'),
(343022, 2, 3430, 3, 2, 0, 'Aeldon Sunbrand', 'Aeldon Sunbrand, captain of the Blood Hawks, keeps order around Falconwing Square. He regards the Wretched as a constant thorn: when they are not endangering themselves by tapping unstable arcane sources, they are hatching half-baked schemes against respectable society, and he cares less whether they blow themselves up than how it would make his men look. He is also plagued by reports of night elves in the woods, most of them unfounded, though the rumors of Darnassian sabotage at the West Sanctum demand a closer look.', 'npc_text 8229; quest 8463 description; quest 8482 reward text; quest 8483 description and reward text; creature_template 15403 subname Captain of the Blood Hawks, faction 1604; quest 9352 description'),
(343023, 2, 3430, 4, 0, 0, 'Prospector Anvilward', 'Prospector Anvilward came to Eversong from Ironforge as an envoy, and Ley-Keeper Caidanis has been showing him the workings of the North Sanctum. The dwarf is gruff with strangers, advising them to be on their way if they want no trouble. He finds the sanctums quite interesting, and Caidanis, with a politeness that sounds a little strained, has remarked that his guest''s enthusiastic interest in their operations is most unexpected.', 'npc_text 8239 (gossip); creature_text 15405, 15420; quest 8482 reward text; quest 8483 description; creature_template 15420 faction 35, gossip_menu 21310'),
(343024, 2, 3430, 5, 2, 0, 'Magister Duskwither', 'Magister Duskwither once taught apprentices at Duskwither Spire, north of the Farstrider Retreat. He has shut the school down for reasons he will not go into, and now waits at the retreat on what he has announced as a sabbatical. He sent his pupil, Apprentice Loralthalis, back to the Spire to finish closing it, and she has not been heard from since. He frets over her, and wonders aloud whether he should have gone himself, and gone in the first place.', 'page_text 2846-2853 (journal); quest 8888 description; quest 8890 reward text; quest 8891 reward text; creature_text 15951 (Good riddance... none shall repeat my mistakes); npc_text 8232'),
(343025, 2, 3430, 6, 2, 0, 'Lord Saltheril', 'Lord Saltheril throws parties at his country haven west of Fairbreeze Village to celebrate the magnificence of Quel''Thalas, and he means to keep throwing them whatever the Scourge may be doing to the south. He hounds Fairbreeze with requests for wine, appetizers and fireworks, cannot remember the faces of those who fetch them, and threatens to complain to the regent lord about the rudeness of the magistrix who must deal with him. His companion Elisara Sunstriker frets that too many undesirables are being let in, and wonders whether, with so many nobles crushed, her lord might soon be elevated.', 'quest 9067 description and request text; quest 9395 description and reward text; creature_text 16144, 16147; npc_text 8374'),
(343026, 2, 3430, 7, 2, 0, 'Larianna Riverwind', 'Larianna Riverwind keeps watch over the Scorched Grove from a lonely tower in southwestern Eversong, and her brother Ardeyn serves at Fairbreeze Village. The grove was burned to halt the Scourge''s taint, and now the treants, long friends of the elves, try to regrow it, so they must be cut down at her word. She calls it a somber task forced by desperate times, curses the Scourge for it, and insists the land must be protected whatever the cost.', 'quest 9258 description and reward text; quest 8473 description and reward text; quest 8474 description and reward text (initials L.R.); quest 10166 description; npc_text 8575'),
(343027, 2, 3430, 8, 0, 0, 'Chieftain Zul''Marosh', 'Chieftain Zul''Marosh rules the Amani of Zeb''Watha on the shore of Lake Elrendar, and the trolls of his lands raid elven territory almost daily. He is cruel even to other trolls. He poisoned the Darkspear Ven''jashi and left him in a cage at Tor''Watha to die. Ven''jashi laughs at death, but he has sworn to hold off the poison until he sees the chieftain''s head, and calls on any enemy of the Amani to bring it.', 'quest 8479 description and reward text; quest 8476 description (daily raids); quest 9360 description and reward text; item 23249 Amani Invasion Plans drops from 15407; DB spawn: Zul''Marosh 15407'),
(343028, 2, 3430, 9, 0, 0, 'Thaelis the Hungerer', 'Thaelis the Hungerer is a notorious ringleader among the Wretched of the Ruins of Silvermoon, lurking in the Commons Hall. Silvermoon City has posted a reward for his head, charging him with repeated crimes against its people, among them the murder of two city guards. At Falconwing Square, where Sergeant Kan''ren has lost two of his men in a month, the bounty has at least one young ranger talking of hunting the beast down himself.', 'quest 8468 description and reward text; npc_text 8698 (Kan''ren); creature_text 16923 (Novice Ranger); warcraft.wiki.gg/wiki/Thaelis_the_Hungerer (Commons Hall); gameobject 180918 wanted poster'),
(343029, 3, 3430, 1, 2, 0, 'Reclaiming Sunstrider Isle', 'The young blood elves of Sunstrider Isle are put to work at once. Magistrix Erona sends them to thin the mana wyrms that have run wild around the Burning Crystals since the Sunwell fell, and then the lynxes those crystals have maddened, keeping their collars in hope of fashioning new restraints. Her assistant Lanthan Perilon has them put down the tenders that once kept the gardens, mourning them even as he asks, before sending them into Falthrien Academy against Felendren the Banished. Between those tasks, Well Watcher Solanian has them gather his scattered belongings and read the placard at Dath''Remar''s shrine, and Arcanist Helion teaches the hardest lesson: control the thirst for magic or become Wretched.', 'quests 8325, 8326, 8327, 8334, 8335 (descriptions and reward texts); quests 8330, 8345, 8346; quests 8347, 9704, 9705, 8350'),
(343030, 3, 3430, 2, 2, 0, 'The Dwarven Spy', 'Trouble at the sanctums begins with small errands. Magister Jaronis of Falconwing Square sends a letter to Ley-Keeper Caidanis at the North Sanctum, who is busy entertaining a dwarven guest and passes the courier on to the West Sanctum. There Ley-Keeper Velania is furious: her warnings about overloading the sanctum went unheeded, a converter has been destroyed, and arcane wraiths are spilling out. Meanwhile Captain Aeldon Sunbrand, weary of unfounded reports of night elves in the woods, cannot ignore the rumors of Darnassian sabotage at the West Sanctum, and sends help to deal with anyone suspicious there.', 'quests 8472, 8895, 9119, 8486 (descriptions and reward texts); quests 8463, 9352, 8482, 8483 (descriptions and reward texts); creature_text 15405, 15420'),
(343031, 3, 3430, 3, 2, 0, 'The Fall of Sunsail Anchorage', 'Ranger Degolien was sent to Fairbreeze Village to look into a Wretched attack on a nearby shipyard, and his call for reinforcements has gone unanswered: the Wretched hold the whole of Sunsail Anchorage. Until reinforcements arrive, he wants their thugs and hooligans taught some discipline. Velendris Whitemorn, whose rangers fled the yard without most of their weapons, wants those armaments back before he moves against the Wretched leader, Aldaron the Reckless. Under the rangers'' protection waits Captain Kelisendra, a merchant who ignored warnings to leave port. The Wretched took her magical goods, Grimscale murlocs carried off the rest of her cargo, and her crew abandoned ship.', 'quests 9256, 8892 (descriptions and reward texts); quests 8480, 9076; quests 8886, 8887 and npc_text 8227 (Kelisendra); quest_template_addon: 8892 PrevQuestID 9256 (Aeldon Sunbrand)'),
(343032, 3, 3430, 4, 2, 0, 'Duskwither''s Folly', 'At the Farstrider Retreat, Magister Duskwither frets over Apprentice Loralthalis, whom he sent back to his abandoned school at Duskwither Spire to shut it down and who has not been heard from since. He wonders aloud whether he should have gone himself. The Spire stands north of the retreat where the road branches east, and strange magical creatures now roam its grounds. Out there the groundskeeper Wyllithen, whom no one told to leave when everyone else did, simply wants the beasts cleared away before his master returns.', 'quests 8888, 8889, 8890 (descriptions and reward texts); quest 8891 description and reward text; page_text 2846-2853; quests 9394, 8894; gameobject 181011 Magister Duskwither''s Journal spawned in the Spire; npc_text 8232 (Duskwither wonders if he should have gone himself)'),
(343033, 3, 3430, 5, 2, 0, 'A Somber Task', 'At Fairbreeze Village, Ardeyn Riverwind explains how a foul taint runs ahead of the Scourge, and how the border runestones once held it back. When the westernmost stone fell, the elves burned the land around it, and he sends help to his sister Larianna at the Scorched Grove. Her request is a painful one. The treants, friends of the elves for years, are trying to regrow the burned forest, and since they cannot be persuaded to stop, they must be stopped by force.', 'quest 9258 description; quest 8473 description and reward text; quest 8474 reward text; quest 10166 description and reward text; item 23228 Old Whitebark''s Pendant drops from 15409; quest 10166 ends at Whitebark''s Spirit 19456'),
(343034, 3, 3430, 6, 2, 0, 'The Amani Threat', 'The blood elves hold little of their old lands, and Lieutenant Dawnrunner of the Farstrider Retreat means to defend every acre until her people can reach Outland. The Amani of Zeb''Watha and Tor''Watha raid daily, so she sends fighters to the villages southeast of the retreat to teach them a lesson. The smith Arathel Sunforge, admiring troll workmanship despite himself, wants the famed hammer of Spearcrafter Otembe. And in a cage at Tor''Watha the dying Darkspear Ven''jashi begs for the head of Chieftain Zul''Marosh before the poison takes him.', 'quest 8476 description; quest 8477 description and reward text; quest 8479 description and reward text; quest 9360 description and reward text; quest 9363 description and reward text');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(343000, 1, 13, 255, 'The wound at the heart of Quel''Thalas has begun to close. With Kil''jaeden turned back on the Isle of Quel''Danas, the Sunwell has been cleansed and rekindled, and it burns pure once more. The Dead Scar still runs black through the forest all the same.', 'creature_text 25319 (Kalecgos: what was once corrupt is now pure); creature_text 26246 (Velen: the heart of M''uru, rebirth of the fount); quel_danas.json 408000 (the Sunwell now burns pure)'),
(343004, 1, 0, 255, 'The outrunners'' fears were well founded. Their courier lies dead in Dawning Lane, slain by the Wretched and stripped of every belonging but one: a package that seems to match the one Magistrix Erona had entrusted to the outrunners.', 'quest 9704 reward text'),
(343004, 2, 0, 255, 'The package is indeed Erona''s, and Outrunner Alarion counts the cost: its courier is the third outrunner lost this month. The guards, she says, need to keep a much closer eye on the Wretched of the ruins.', 'quest 9705 description and reward text'),
(343007, 1, 0, 255, 'The rumors were not all idle. Night elf scouts have been found skulking about the West Sanctum, and whatever brought them there, it is Captain Sunbrand at Falconwing Square who must hear of it.', 'quest 9352 reward text; quest 8482 description; DB spawns: Darnassian Scout 15968 near Ley-Keeper Velania 15401'),
(343007, 2, 0, 255, 'One scout carried papers: detailed maps of strategic buildings across Eversong, a careful sketch of an arcane sanctum, and pages of notes that proved to be Dwarvish. They told a stranger story than sabotage. Their author called the elves'' work reckless and dangerous, yet had not caused the malfunction, only been sent to watch its results. Captain Sunbrand read them as the work of the envoy from Ironforge.', 'quest 8482 reward text'),
(343013, 1, 0, 255, 'The soil gave its answer, and the Scourge came for the one asking. Undead fell on Mirveda as she worked her enchantments on the samples, and when they were beaten back her findings were grim: the very nature of the soil has been altered, and the taint cannot be reversed.', 'quest 8487 reward text; quest 8488 description and reward text; creature_text 15402'),
(343013, 2, 0, 255, 'Mirveda''s notes went to her old mentor for review. Magistrix Dawnstrider found them shocking, for they mean the damage along the Dead Scar is permanent. She sent word to the grand magister at once, and called it one more reason for the sin''dorei to leave this world and seek their true fate in Outland.', 'quest 9255 description and reward text'),
(343014, 1, 0, 255, 'The Wretched struck. They fell on the two apprentices and carried off mana crystals, wands and spellbooks, and though Meledor drove them off with a well placed fireball, the thieves threw what they had into the river, Antheol''s grimoire among it.', 'quest 9035 description and reward text; quest 9062 description'),
(343014, 2, 0, 255, 'The grimoire came out of the water soaked through. Dreading their master''s temper, the apprentices tried to buy a passerby''s help: carry the book to Antheol and tell him it had merely been dropped in a puddle. Antheol heard the whole story instead, and commended the one who told him the truth.', 'quest 9062 reward text; quest 9064 description and reward text'),
(343014, 3, 0, 255, 'Antheol''s discipline was swift. Never trust someone else to lie for you, he warns. His disciplinary rod found both apprentices on the road west of the Dead Scar and left them briefly transformed, and their apprenticeships stay suspended until they earn them back.', 'quest 9066 description and reward text; creature_text 15941, 15945'),
(343016, 1, 0, 255, 'Not every apprentice left with the magister. When the Spire''s three power sources were finally shut down, it became clear that some of Duskwither''s pupils had fallen to their craving for magic inside, becoming Wretched in the halls where they once studied. Apprentice Loralthalis waits outside, hoping to slip in and recover their remains.', 'quest 8889 reward text; quest 8890 description'),
(343016, 2, 0, 255, 'A journal left behind in the Spire explains the disaster. In it Magister Duskwither recorded his search for a safe source of magic for his people, and a new process for filtering the impurities out of corrupted fel power. Apprentice after apprentice withered into Wretched as the work went on, until he emptied the school in haste under cover of a sabbatical.', 'quest 8891 description; page_text 2846-2853 (journal); gameobject 181011 Magister Duskwither''s Journal'),
(343019, 1, 0, 255, 'The villages serve a larger purpose. Battle plans taken from Zul''Marosh mark the Farstrider Retreat and Fairbreeze Village, and Lieutenant Dawnrunner reads them plainly: the daily raids have kept the Farstriders pinned at their lodge while the Amani prepare an attack on Fairbreeze.', 'quest 9360 description and reward text'),
(343021, 1, 0, 255, 'Felendren''s fall was noticed far beyond the isle. Magister Duskwither, searching for a safe source of magic for his people, wrote of it in his journal when the news reached him, and took it as a spur to redouble his own research, work that would end in disaster at his Spire.', 'page_text 2848 (Duskwither''s journal on Felendren); quest 8891 description'),
(343022, 1, 0, 255, 'Papers from a night elf spy settled the question, though not as anyone expected. They were written in Dwarvish, and Sunbrand named their author at once: the envoy from Ironforge. Fools, he says, to trust anyone of the Alliance. Since the spy could neither be killed openly nor safely captured, he ordered him quietly removed.', 'quest 8482 reward text; quest 8483 description'),
(343022, 2, 0, 255, 'With the envoy''s head delivered, the deed is done as quietly as Sunbrand wished, and he counts it a great service to the sin''dorei. He has passed word to the ranger general, and he promises that the dwarves will pay dearly for their treason.', 'quest 8483 reward text'),
(343023, 1, 0, 255, 'His curiosity proved more than diplomatic. Notes in Dwarvish, carried by a night elf scout, called the elves'' experiments reckless and showed that their author had been sent to watch the results of the West Sanctum''s malfunction. Captain Sunbrand read them as Anvilward''s work and ordered his quiet death, for Silvermoon could not let it be known that it had welcomed a spy.', 'quest 8482 reward text; quest 8483 description'),
(343023, 2, 0, 255, 'Anvilward was lured into the sanctum on the promise of something worth seeing, and when he sensed the ambush he warned that he would not go down quietly. He fell all the same, and his head was taken as proof for Captain Sunbrand.', 'gossip_menu 21310, 21311 (option: something to show you right inside this building); creature_text 15420 (trick, will not go down quietly); quest 8483 reward text'),
(343024, 1, 0, 255, 'The news from the Spire broke him. Some of his apprentices had become Wretched, and Duskwither cried that it was all his fault: his investigation into purifying alternative sources of magic had got out of hand before he could stop it. He has blood on his hands, he says, and his only consolation is that their tortured souls no longer linger in that state where a blood elf is better off dead.', 'quest 8890 description and reward text'),
(343024, 2, 0, 255, 'His journal, brought back from the Spire, holds the rest. Hoping for a safe supplement to the lost Sunwell, he set out to filter the impurities from corrupted fel power, and an early success drew most of his students into the work. Then his chief apprentice Telethayon withered before his eyes, and more followed. He announced the sabbatical only to get the others away. Calling the tome the proof of his crime, he burns it so none can repeat his mistakes.', 'page_text 2846-2853 (journal); quest 8891 reward text; creature_text 15951 (Good riddance... none shall repeat my mistakes)'),
(343026, 1, 0, 255, 'Among the treants who fell was Old Whitebark, their elder, and his pendant found its way back to its maker. Larianna gave it to him long ago, after his people helped hers rebuild their village, and she first met him beside the grove''s runestone. Steadying herself, she asks that it be buried there to lay her old friend''s memory to rest.', 'quest 8474 description and reward text; quest 10166 description'),
(343027, 1, 0, 255, 'Ven''jashi had his reasons. Zul''Marosh burned his village, and the Darkspear killed many Amani before he was caught and caged. When the chieftain''s head was brought to him at last, he gave up a gift he had hidden in the sand and let the poison take him.', 'quest 8479 reward text'),
(343027, 2, 0, 255, 'Zul''Marosh carried battle plans in a tongue their finder cannot read, but their map is plain enough: it marks the positions of the Farstrider Retreat and Fairbreeze Village, the first sign that the trolls intend more than raids.', 'quest 9360 description; item 23249 Amani Invasion Plans drops from 15407'),
(343028, 1, 0, 255, 'The Hungerer''s crimes have caught up with him. Thaelis lies dead among the Wretched who followed him, and the bounty Silvermoon posted on his head, for the murder of two city guards among much else, can at last be claimed.', 'quest 8468 description'),
(343028, 2, 0, 255, 'His head has gone to Sergeant Kan''ren at Falconwing Square, who pays out the city''s reward. The scoundrel has finally met his fate, the sergeant says, and things should be quiet with the Wretched for a while.', 'quest 8468 reward text'),
(343029, 1, 0, 255, 'Felendren''s head is proof enough. Those who bring it back have succeeded where Felendren failed and may yet prove worthy of their people, though the banished one, they are warned, was only a symptom of a larger problem. Erona''s charges are sent south to aid the outrunners who carry goods between the isle and the mainland.', 'quest 8335 request and reward text; quest 8347 description'),
(343029, 2, 0, 255, 'The road south proves as deadly as the outrunners feared. In Dawning Lane lies their latest courier, slain by the Wretched and stripped of every belonging except one package, which looks very much like the one Magistrix Erona sent south.', 'quest 9704 description and reward text'),
(343029, 3, 0, 255, 'The package is Erona''s, and Outrunner Alarion counts the cost: the third outrunner lost this month. Short of hands, the outrunners entrust it to the newcomers, who must carry it through the ruins, keeping to the safety of Dawning Lane, to the inn at Falconwing Square.', 'quest 9705 reward text; quest 8350 description'),
(343030, 1, 0, 255, 'The rumors had substance. Night elf scouts were found lurking about the West Sanctum, and whatever they were doing there, word of them must go back to Captain Sunbrand at Falconwing Square, who sent help to the sanctum in the first place.', 'quest 9352 reward text; quest 8482 description'),
(343030, 2, 0, 255, 'One scout had carried papers: maps of strategic buildings across Eversong, a sketch of a sanctum, and notes that Sunbrand knew at once for Dwarvish. Their author called the elves'' experiments reckless and dangerous, and had not caused the malfunction but been sent to watch its results. The captain named the culprit, the Ironforge envoy Prospector Anvilward, and ordered him silenced quietly at the North Sanctum, lest word spread that Silvermoon had let a spy into its lands.', 'quest 8482 reward text; quest 8483 description'),
(343030, 3, 0, 255, 'Anvilward was drawn into the North Sanctum on the pretext of something to show him, and when he saw the trap he swore he would not go down quietly. He fell all the same. Sunbrand passed word to the ranger general and promised that the dwarves would pay dearly for their treason.', 'gossip_menu 21311; creature_text 15420; quest 8483 reward text'),
(343031, 1, 0, 255, 'The Wretched are so sunk in their stupor that they have not noticed the rangers have their weapons back. Velendris judges it time for a decisive attack, and means to make an example of Aldaron, who was spotted on the top floor of the building by the anchorage.', 'quest 8480 reward text; quest 9076 description'),
(343031, 2, 0, 255, 'The decisive attack found its mark. Aldaron the Reckless lies dead on the top floor of the building by the anchorage, the example Velendris wanted made of him. The Wretched still hold the yard, but they have lost the one who led them into it.', 'quest 9076 description'),
(343031, 3, 0, 255, 'Kelisendra''s cargo has come back from the Grimscale huts, and it has saved her from ruin. Once the rangers help her with it she means to get out of the anchorage at last, and to come back when Velendris has retaken the shipyard.', 'quest 8886 reward text'),
(343031, 4, 0, 255, 'The murlocs had taken more than cargo. Among their plunder were Kelisendra''s navigation rutters, which she never knew were missing, and without them she would have no chance of sailing again once the anchorage is retaken and her ship repaired.', 'quest 8887 reward text'),
(343032, 1, 0, 255, 'Loralthalis is found outside the Spire, safe, but too late to do what she was sent for. Strange magical creatures have overrun the building, and its three power sources, each in a different place inside, still burn, a task beyond her own skill to shut down.', 'quest 8888 reward text; quest 8889 description'),
(343032, 2, 0, 255, 'Once the power is cut, the truth comes out. Some of Loralthalis''s fellow apprentices have fallen to their addiction inside the Spire, and she means to stay a while and slip in to recover their remains. She sends word back to the magister that she is well, but that his students have become Wretched.', 'quest 8889 reward text; quest 8890 description'),
(343032, 3, 0, 255, 'Duskwither takes the news as a blow. It is all his fault, he says: his investigation into purifying alternative sources of magic got out of hand before he could stop it. He confesses he has blood on his hands, and takes small comfort that his former pupils no longer linger in a state where a blood elf is better off dead.', 'quest 8890 reward text'),
(343032, 4, 0, 255, 'His own journal, left behind in the Spire, records the rest: shocking attempts at filtering corrupted fel energies, the apprentices who withered one after another, and the hurried evacuation that left the power running. Returned to its author, the journal is condemned to the fire, so that no one else can fall prey to its contents.', 'quest 8891 description and reward text; page_text 2846-2853'),
(343033, 1, 0, 255, 'Among the fallen is Old Whitebark, elder of the treants, and among his remains lies a pendant etched with the initials L.R. It is Larianna''s own gift: she gave it to him when his people helped rebuild her village. She asks that it be buried by the grove''s runestone, where she first met him.', 'quest 8474 description and reward text; quest 10166 description; item 23228 Old Whitebark''s Pendant drops from 15409'),
(343033, 2, 0, 255, 'There Whitebark''s spirit lingers, and it admits defeat. The land has changed forever, it says, and nothing will be the same, but perhaps one day, long after the elves are gone, a new tree will grow on that spot among the burnt forest and the husks of dead treants.', 'quest 10166 reward text'),
(343034, 1, 0, 255, 'When Zul''Marosh''s head is brought to him, Ven''jashi tells why it mattered: the chieftain burned his village, and the Darkspear killed many Amani before they caged him. He gives up a gift hidden in the sand, and as the poison spreads at last, he goes to his rest.', 'quest 8479 reward text'),
(343034, 2, 0, 255, 'The chieftain yielded more than his head. His battle plans mark the Farstrider Retreat and Fairbreeze Village, and Dawnrunner sees the truth at once: the raids have kept her rangers pinned at the retreat while the Amani plan an attack on Fairbreeze. Even with Zul''Marosh dead, she rushes word to Ranger Degolien that the village must ready itself, with reinforcements to follow.', 'quest 9360 reward text; quest 9363 description');
